def SMA_plot_picture(RR_PacketLoss, DQN_PacketLoss):

    window_size = 20
    
    # 轉換為DataFrame
    df_DQN = pd.DataFrame(DQN_PacketLoss, columns=['UE1', 'UE2'])
    df_RR = pd.DataFrame(RR_PacketLoss, columns=['UE1', 'UE2'])
    # df_BET = pd.DataFrame(BET_PacketLoss, columns=['UE1', 'UE2'])
    
    # 计算各 DataFrame 的长度
    length_DQN = len(df_DQN)
    length_RR = len(df_RR)

    # 确定最短的 DataFrame 长度
    min_length = min(length_DQN, length_RR)
    min_ticks = np.arange(min_length)
    
    # 計算SMA
    DQN_sma_ue1 = df_DQN['UE1'].rolling(window=window_size, min_periods=1).mean()
    DQN_sma_ue2 = df_DQN['UE2'].rolling(window=window_size, min_periods=1).mean()
    RR_sma_ue1 = df_RR['UE1'].rolling(window=window_size, min_periods=1).mean()
    RR_sma_ue2 = df_RR['UE2'].rolling(window=window_size, min_periods=1).mean()
    # BET_sma_ue1 = df_BET['UE1'].rolling(window=window_size, min_periods=1).mean()
    # BET_sma_ue2 = df_BET['UE2'].rolling(window=window_size, min_periods=1).mean()
    
    # ------------------------------------------------------------------------------------------------
    # 第一張圖：UE1封包佇列累積量
    plt.figure(figsize=(10, 5))
    plt.plot(min_ticks, DQN_sma_ue1[:min_length], label='DQN Packet Queue Length (UE1)', color='darkred')
    plt.plot(min_ticks, RR_sma_ue1[:min_length], label='RR Packet Queue Length (UE1)', color='darkgreen')
    # plt.plot(min_ticks, BET_sma_ue1[:min_length], label='BET Packet Queue Length', color='olive')
    
    print(f"ue1 : RR = {RR_sma_ue1[min_length-1]}, DQN = {DQN_sma_ue1[min_length-1]}")
    
    plt.legend(prop={'size': 15})
    plt.title('Video Packet Queue Length (SMA)')
    plt.xlabel('Time (seconds)')
    
    # 设置 y 轴为对数刻度，底数为 10
    plt.yscale('log', base=10)
    # 设置 y 轴的刻度
    ticks = [10**i for i in range(6, 10)]  # Generates [1, 10, 100, ..., 10^8]
    plt.yticks(ticks, [f"10^{i}" for i in range(6, 10)])  # Labels as 10^0, 10^1, ..., 10^8
    
    plt.ylabel('Log10 of Packet Loss (bits)')
    plt.grid(True)
    plt.savefig(f'Video_packet_loss_plot_SMA.png')
    plt.close()
    
    # ------------------------------------------------------------------------------------------------
    
    # 第二張圖：UE2封包丟失率
    plt.figure(figsize=(10, 5))
    plt.plot(min_ticks, DQN_sma_ue2[:min_length], label='DQN Packet Loss of (UE2)', color='red')
    plt.plot(min_ticks, RR_sma_ue2[:min_length], label='RR Packet Loss of (UE2)', color='green')
    # plt.plot(min_ticks, BET_sma_ue2[:min_length], label='BET Packet Loss of (UE2)', color='olivedrab')
    
    plt.legend(prop={'size': 15})
    plt.title('Real-time Packet Loss Over Time (SMA)')
    plt.xlabel('Time (seconds)')
    
    print(f"ue2 : RR = {RR_sma_ue2[min_length-1]}, DQN = {DQN_sma_ue2[min_length-1]}\n")
    
    # 设置 y 轴为对数刻度，底数为 10
    # plt.yscale('log', base=10)
    # # 设置 y 轴的刻度
    # ticks = [10**i for i in range(9)]  # Generates [1, 10, 100, ..., 10^8]
    # plt.yticks(ticks, [f"10^{i}" for i in range(9)])  # Labels as 10^0, 10^1, ..., 10^8
    
    plt.ylabel('Log10 of Packet Loss (bits)')
    plt.grid(True)
    plt.savefig(f'Real-time_packet_loss_plot_SMA.png')
    plt.close()


# 轉換為DataFrame
df_DQN = pd.DataFrame(DQN_PacketLoss, columns=['UE1', 'UE2'])
df_RR = pd.DataFrame(RR_PacketLoss, columns=['UE1', 'UE2'])
# df_BET = pd.DataFrame(BET_PacketLoss, columns=['UE1', 'UE2'])

# 计算各 DataFrame 的长度
length_DQN = len(df_DQN)
length_RR = len(df_RR)
min_length = min(length_DQN, length_RR)

for i in range(1,min_length):
    SMA_plot_picture(RR_PacketLoss[:i], DQN_PacketLoss[:i])
    time.sleep(1)